<?php

/**
 * The harness's composer.json and phpunit.xml: omnishare from its checkout
 * (a path repository), PHPUnit, the package's tests. Files are rewritten only
 * when they change, so the entrypoint knows when to install.
 */
$package = '/omnishare';
$out = '/harness';

$composer = [
    'name' => 'omnisense/omnishare-harness',
    'description' => 'omnisense/omnishare from its checkout: generated by docker/harness/setup.php, do not edit.',
    'type' => 'project',
    'license' => 'MIT',
    'repositories' => [['type' => 'path', 'url' => $package, 'options' => ['symlink' => true, 'versions' => ['omnisense/omnishare' => '1.x-dev']]]],
    'require' => ['php' => '>=8.2', 'omnisense/omnishare' => '1.x-dev'],
    'require-dev' => ['phpunit/phpunit' => '^11.0'],
    'autoload-dev' => ['psr-4' => ['Omnishare\\Tests\\' => "$package/Tests/"]],
    'minimum-stability' => 'dev',
    'prefer-stable' => true,
    'config' => ['sort-packages' => true],
];
$json = json_encode($composer, \JSON_PRETTY_PRINT | \JSON_UNESCAPED_SLASHES)."\n";
if (!is_file("$out/composer.json") || file_get_contents("$out/composer.json") !== $json) {
    file_put_contents("$out/composer.json", $json);
    echo "composer.json composed\n";
}

$xml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<phpunit xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:noNamespaceSchemaLocation=\"vendor/phpunit/phpunit/phpunit.xsd\" bootstrap=\"vendor/autoload.php\" colors=\"true\" failOnWarning=\"true\" cacheDirectory=\".phpunit.cache\">\n    <testsuites>\n        <testsuite name=\"omnishare\"><directory>$package/Tests</directory></testsuite>\n    </testsuites>\n</phpunit>\n";
if (!is_file("$out/phpunit.xml") || file_get_contents("$out/phpunit.xml") !== $xml) {
    file_put_contents("$out/phpunit.xml", $xml);
}
